import type { AiSettings } from "../settings/types";
import { validateAiSettings } from "../settings/secrets";

export interface AiChatMessage {
  role: "system" | "user" | "assistant";
  content: string;
}

export interface OpenAiClientOptions {
  fetch?: typeof fetch;
}

export interface AiCompletionRequest {
  messages: readonly AiChatMessage[];
}

function endpoint(baseUrl: string, path: string): string {
  return `${baseUrl.replace(/\/+$/, "")}/${path}`;
}

function requestHeaders(settings: AiSettings): Record<string, string> {
  const headers: Record<string, string> = { ...settings.customHeaders };
  for (const name of Object.keys(headers)) {
    if (["authorization", "openai-organization", "content-type"].includes(name.toLowerCase())) {
      delete headers[name];
    }
  }
  headers.Authorization = `Bearer ${settings.apiKey}`;
  if (settings.organizationId.trim()) {
    headers["OpenAI-Organization"] = settings.organizationId;
  } else {
    delete headers["OpenAI-Organization"];
  }
  return headers;
}

function validateMessages(messages: readonly AiChatMessage[]): void {
  if (!Array.isArray(messages) || messages.length === 0) throw new Error("AI messages are required");
  for (const message of messages) {
    if (!["system", "user", "assistant"].includes(message.role) || typeof message.content !== "string" || !message.content.trim()) {
      throw new Error("Invalid AI message");
    }
  }
}

/** Small OpenAI-compatible transport. It deliberately has no logging side effects. */
export class OpenAiClient {
  readonly #settings: AiSettings;
  readonly #fetch: typeof fetch;

  constructor(settings: AiSettings, fetchImpl?: typeof fetch | OpenAiClientOptions, options: OpenAiClientOptions = {}) {
    this.#settings = { ...settings, customHeaders: { ...settings.customHeaders } };
    const suppliedFetch = typeof fetchImpl === "function" ? fetchImpl : fetchImpl?.fetch;
    this.#fetch = suppliedFetch ?? options.fetch ?? fetch;
  }

  async testConnection(): Promise<void> {
    validateAiSettings(this.#settings);
    const response = await this.#fetch(endpoint(this.#settings.apiUrl, "models"), {
      method: "GET",
      headers: requestHeaders(this.#settings),
      body: undefined,
    });
    if (!response.ok) throw new Error(`AI connection failed (${response.status})`);
  }

  async complete(messagesOrRequest: readonly AiChatMessage[] | AiCompletionRequest): Promise<string> {
    validateAiSettings(this.#settings);
    const messages = "messages" in messagesOrRequest ? messagesOrRequest.messages : messagesOrRequest;
    validateMessages(messages);
    const response = await this.#fetch(endpoint(this.#settings.apiUrl, "chat/completions"), {
      method: "POST",
      headers: (() => {
        const headers = requestHeaders(this.#settings);
        headers["Content-Type"] = "application/json";
        return headers;
      })(),
      body: JSON.stringify({ model: this.#settings.model, messages }),
    });
    if (!response.ok) throw new Error(`AI request failed (${response.status})`);
    let payload: unknown;
    try {
      payload = await response.json();
    } catch {
      throw new Error("AI response was not valid JSON");
    }
    const content = (payload as { choices?: Array<{ message?: { content?: unknown } }> })
      .choices?.[0]?.message?.content;
    if (typeof content !== "string") throw new Error("AI response did not contain message content");
    return content;
  }
}

export function createOpenAiClient(settings: AiSettings, fetchImpl?: typeof fetch): OpenAiClient {
  return new OpenAiClient(settings, fetchImpl);
}

import type { AnalysisResult } from "../db/types";

export const REALITY_CONSTRAINT =
  "Do not invent or infer the user's experience, skills, education, achievements, employers, or quantitative results. If information is uncertain or missing, ask the user before making a claim. 不得虚构经历、技能、学历、成果或量化数据；不确定内容必须先询问用户。";

export interface AiContextInput {
  resumeText: string;
  jdText: string;
  analysisResult?: Pick<
    AnalysisResult,
    | "coverage"
    | "matchedKeywords"
    | "weakMatches"
    | "missingKeywords"
    | "evidence"
    | "uncertainItems"
    | "recommendations"
  >;
}

export interface AiContext {
  system: string;
  user: string;
}

export function buildAiContext(input: AiContextInput): AiContext {
  if (!input.resumeText.trim()) throw new Error("Confirmed resume text is required");
  if (!input.jdText.trim()) throw new Error("Confirmed JD text is required");

  const analysis = input.analysisResult
    ? JSON.stringify({
        coverage: input.analysisResult.coverage,
        matchedKeywords: input.analysisResult.matchedKeywords,
        weakMatches: input.analysisResult.weakMatches,
        missingKeywords: input.analysisResult.missingKeywords,
        evidence: input.analysisResult.evidence,
        uncertainItems: input.analysisResult.uncertainItems,
        recommendations: input.analysisResult.recommendations,
      })
    : "No local matching result was provided.";

  return {
    system: `${REALITY_CONSTRAINT}\nProvide evidence-based suggestions only. Mark every proposed change as a suggestion; never modify the source resume file.`,
    user: [
      "Use only the confirmed resume text and confirmed job-description text below.",
      "CONFIRMED RESUME TEXT:",
      input.resumeText,
      "CONFIRMED JOB DESCRIPTION TEXT:",
      input.jdText,
      "OPTIONAL LOCAL MATCHING RESULT (text evidence only):",
      analysis,
    ].join("\n\n"),
  };
}

import { requestToPromise, runTransaction } from "../../db/database";
import { STORE_NAMES } from "../../db/schema";
import { assertAbsoluteIsoTimestamp, nextUpdatedTimestamp } from "../../db/timestamps";
import type { AiConversation, AiMessage } from "../../db/types";
import { buildAiContext, type AiContextInput } from "../../ai/prompts";
import type { AiChatMessage } from "../../ai/client";

export interface AiCompletionClient {
  complete(messages: readonly AiChatMessage[]): Promise<string>;
}

export interface AiConversationServiceDependencies {
  client: AiCompletionClient;
  now?: () => string;
  createId?: () => string;
}

function defaultNow(): string { return new Date().toISOString(); }
function defaultCreateId(): string { return crypto.randomUUID(); }

function validateMessage(message: Pick<AiMessage, "role" | "content">): void {
  if (!["system", "user", "assistant"].includes(message.role)) throw new Error("Invalid AI message role");
  if (typeof message.content !== "string" || !message.content.trim()) throw new Error("AI message content is required");
}

export class AiConversationService {
  readonly #database: IDBDatabase;
  readonly #client: AiCompletionClient;
  readonly #now: () => string;
  readonly #createId: () => string;

  constructor(database: IDBDatabase, dependencies: AiConversationServiceDependencies) {
    this.#database = database;
    this.#client = dependencies.client;
    this.#now = dependencies.now ?? defaultNow;
    this.#createId = dependencies.createId ?? defaultCreateId;
  }

  async getConversation(applicationId: string): Promise<AiConversation | undefined> {
    return runTransaction(this.#database, STORE_NAMES.aiConversations, "readonly", async (tx) => {
      const records = await requestToPromise<AiConversation[]>(
        tx.objectStore(STORE_NAMES.aiConversations).index("applicationId").getAll(applicationId),
      );
      return records.sort((a, b) => b.updatedAt.localeCompare(a.updatedAt))[0];
    });
  }

  async appendMessage(applicationId: string, message: Pick<AiMessage, "role" | "content">): Promise<AiConversation> {
    validateMessage(message);
    return runTransaction(this.#database, STORE_NAMES.aiConversations, "readwrite", async (tx) => {
      const store = tx.objectStore(STORE_NAMES.aiConversations);
      const existing = (await requestToPromise<AiConversation[]>(store.index("applicationId").getAll(applicationId)))
        .sort((a, b) => b.updatedAt.localeCompare(a.updatedAt))[0];
      const timestamp = this.#now();
      assertAbsoluteIsoTimestamp(timestamp, "AiConversation.createdAt");
      const createdMessage: AiMessage = { id: this.#createId(), role: message.role, content: message.content, createdAt: timestamp };
      const conversation: AiConversation = existing
        ? { ...existing, messages: [...existing.messages, createdMessage], updatedAt: nextUpdatedTimestamp(timestamp, existing.updatedAt) }
        : { id: this.#createId(), applicationId, messages: [createdMessage], createdAt: timestamp, updatedAt: timestamp };
      await requestToPromise(store.put(conversation));
      return conversation;
    });
  }

  /** Complete remotely first; only a successful response is persisted locally. */
  async sendMessage(applicationId: string, contentOrMessage: string | Pick<AiMessage, "role" | "content">, context: AiContextInput): Promise<AiConversation> {
    const content = typeof contentOrMessage === "string" ? contentOrMessage : contentOrMessage.content;
    if (typeof contentOrMessage !== "string" && contentOrMessage.role !== "user") {
      throw new Error("AI send message must have user role");
    }
    validateMessage({ role: "user", content });
    const aiContext = buildAiContext(context);
    const existing = await this.getConversation(applicationId);
    const messages: AiChatMessage[] = [
      { role: "system", content: aiContext.system },
      { role: "user", content: aiContext.user },
      ...(existing?.messages ?? []).map(({ role, content: messageContent }) => ({ role, content: messageContent })),
      { role: "user", content },
    ];
    const assistantContent = await this.#client.complete(messages);
    validateMessage({ role: "assistant", content: assistantContent });

    return runTransaction(this.#database, STORE_NAMES.aiConversations, "readwrite", async (tx) => {
      const store = tx.objectStore(STORE_NAMES.aiConversations);
      const latest = (await requestToPromise<AiConversation[]>(store.index("applicationId").getAll(applicationId)))
        .sort((a, b) => b.updatedAt.localeCompare(a.updatedAt))[0];
      const timestamp = this.#now();
      assertAbsoluteIsoTimestamp(timestamp, "AiConversation.updatedAt");
      const userMessage: AiMessage = { id: this.#createId(), role: "user", content, createdAt: timestamp };
      const assistantMessage: AiMessage = { id: this.#createId(), role: "assistant", content: assistantContent, createdAt: timestamp };
      const conversation: AiConversation = latest
        ? { ...latest, messages: [...latest.messages, userMessage, assistantMessage], updatedAt: nextUpdatedTimestamp(timestamp, latest.updatedAt) }
        : { id: this.#createId(), applicationId, messages: [userMessage, assistantMessage], createdAt: timestamp, updatedAt: timestamp };
      await requestToPromise(store.put(conversation));
      return conversation;
    });
  }

  get(applicationId: string): Promise<AiConversation | undefined> { return this.getConversation(applicationId); }
  refresh(applicationId: string): Promise<AiConversation | undefined> { return this.getConversation(applicationId); }
  append(applicationId: string, message: Pick<AiMessage, "role" | "content">): Promise<AiConversation> { return this.appendMessage(applicationId, message); }
  send(applicationId: string, content: string | Pick<AiMessage, "role" | "content">, context: AiContextInput): Promise<AiConversation> { return this.sendMessage(applicationId, content, context); }
}

import type { ResumeLibraryService } from "../../features/resumes/resumeLibrary";
import type { AnalysisResult, Application, Resume, Stage } from "../../db/types";

export interface ApplicationBoardOptions {
  applicationService?: {
    listApplications(): Promise<Application[]>;
    createApplication(input: Record<string, unknown>): Promise<Application>;
    updateApplication(id: string, patch: Record<string, unknown>): Promise<Application>;
    changeStage(id: string, stageId: string): Promise<Application>;
    bindResume(id: string, resumeId: string): Promise<Application>;
    updateNote(id: string, note: string): Promise<Application>;
    listTimeline(id: string): Promise<any[]>;
    listResumeUsageHistory(id: string): Promise<any[]>;
    previewArchive(id: string): Promise<ActionPreview>;
    confirmArchive(id: string, preview: ActionPreview): Promise<Application>;
    previewDelete(id: string): Promise<ActionPreview>;
    confirmDelete(id: string, preview: ActionPreview): Promise<void>;
  };
  stageService?: {
    ensureDefaultStages(): Promise<Stage[]>;
    listStages(): Promise<Stage[]>;
    updateStage(id: string, patch: Record<string, unknown>): Promise<Stage>;
    reorderStages(ids: readonly string[]): Promise<Stage[]>;
    previewDelete(id: string): Promise<{ id: string; name: string; kind: string; applicationCount: number }>;
    deleteStage(id: string, options?: Record<string, unknown>): Promise<void>;
    getOutcomeCounts(): Promise<{ offer: number; rejected: number; withdrawn: number }>;
  };
  jobDescriptionService?: {
    ingestPaste(applicationId: string, text: string): Promise<any>;
    ingestFile?: (applicationId: string, file: File) => Promise<any>;
    confirmText(jobDescriptionId: string, text: string): Promise<any>;
  };
  resumeLibrary?: Pick<ResumeLibraryService, "search" | "getConfirmedText">;
  matchingService?: {
    run(applicationId: string, resumeId: string): Promise<AnalysisResult>;
    listHistory(applicationId: string, resumeId?: string, mode?: "local" | "ai"): Promise<AnalysisResult[]>;
    get(id: string): Promise<AnalysisResult | undefined>;
  };
}

type ActionPreview = { id: string; company?: string; position?: string; name?: string; resumeUsageCount?: number; timelineEventCount?: number; applicationCount?: number; archived?: boolean; kind?: string };

const JOB_TYPES = ["graduate", "internship", "tech", "general", "other"] as const;
const WORK_MODES = ["onsite", "remote", "hybrid", "unknown"] as const;

const defaultApplicationService = {
  listApplications: async () => [] as Application[],
  createApplication: async (input: Record<string, unknown>) => ({ ...input, id: crypto.randomUUID(), createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() } as Application),
  updateApplication: async (id: string, patch: Record<string, unknown>) => ({ ...patch, id } as Application),
  changeStage: async () => undefined as never,
  bindResume: async () => undefined as never,
  updateNote: async () => undefined as never,
  listTimeline: async () => [],
  listResumeUsageHistory: async () => [],
  previewArchive: async () => undefined as never,
  confirmArchive: async () => undefined as never,
  previewDelete: async () => undefined as never,
  confirmDelete: async () => undefined,
};

const defaultStageService = {
  ensureDefaultStages: async () => [] as Stage[],
  listStages: async () => [] as Stage[],
  updateStage: async () => undefined as never,
  reorderStages: async () => [],
  previewDelete: async () => undefined as never,
  deleteStage: async () => undefined,
  getOutcomeCounts: async () => ({ offer: 0, rejected: 0, withdrawn: 0 }),
};

export function createApplicationBoard(
  documentRef: Document,
  options: ApplicationBoardOptions = {},
): HTMLElement {
  const applicationService = options.applicationService ?? defaultApplicationService;
  const stageService = options.stageService ?? defaultStageService;
  const root = documentRef.createElement("section");
  root.className = "application-board";
  root.setAttribute("aria-labelledby", "application-board-title");
  root.innerHTML = `
    <div class="section-heading application-board__heading">
      <div><p class="section-label">申请管理</p><h2 id="application-board-title">职位申请</h2></div>
      <div class="application-board__controls">
        <button type="button" data-view="board" aria-pressed="true">看板</button>
        <button type="button" data-view="list" aria-pressed="false">列表</button>
        <label for="application-job-type">筛选职位类型</label>
        <select id="application-job-type"><option value="">全部类型</option>${JOB_TYPES.map((value) => `<option value="${value}">${value}</option>`).join("")}</select>
      </div>
    </div>
    <div class="application-board__status" role="status" aria-live="polite" aria-atomic="true">正在读取职位...</div>
    <form class="application-form" data-form="application">
      <div class="application-form__header"><h3 data-form-title>创建职位</h3><button type="button" data-action="cancel-edit" hidden>取消编辑</button></div>
      <div class="application-form__grid">
        <label for="application-company">公司<input id="application-company" name="company" required /></label>
        <label for="application-position">职位<input id="application-position" name="position" required /></label>
        <label>职位类型<select name="jobType">${JOB_TYPES.map((value) => `<option value="${value}">${value}</option>`).join("")}</select></label>
        <label>地点<input name="location" /></label>
        <label>工作模式<select name="workMode">${WORK_MODES.map((value) => `<option value="${value}">${value}</option>`).join("")}</select></label>
        <label>薪资<input name="salaryText" /></label>
        <label>来源<input name="source" /></label>
        <label for="application-job-url">招聘网址<input id="application-job-url" name="jobUrl" type="url" /></label>
        <label>截止时间<input name="deadline" type="datetime-local" /></label>
        <label>联系人<input name="contact" /></label>
        <label>优先级<input name="priority" type="number" min="0" step="1" value="0" /></label>
        <label>阶段<select name="stageId"></select></label>
        <label>当前简历<select name="currentResumeId"><option value="">暂不绑定</option></select></label>
      </div>
      <label>职位备注<textarea name="note" rows="2"></textarea></label>
      <label for="application-jd-text">确认 JD 文本<textarea id="application-jd-text" name="jdText" rows="5" placeholder="粘贴职位描述"></textarea></label>
      <label class="application-file-label">上传 JD（PDF/DOCX）<input name="jdFile" type="file" accept=".pdf,.docx,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document" /></label>
      <div class="application-form__actions"><button type="submit" data-submit-application>保存职位</button><button type="button" data-action="confirm-jd" hidden>确认 JD 文本</button></div>
    </form>
    <div class="application-board-view" data-view-panel="board"></div>
    <div class="application-list-view" data-view-panel="list" hidden></div>
    <section class="stage-manager" aria-labelledby="stage-manager-title">
      <div class="section-heading"><h3 id="stage-manager-title">阶段管理</h3><span class="stage-outcome-counts" role="status"></span></div>
      <div class="stage-manager__list"></div>
    </section>
    <section class="application-detail" aria-labelledby="application-detail-title" hidden>
      <div class="section-heading"><h3 id="application-detail-title">职位详情</h3><button type="button" data-action="close-detail">关闭</button></div>
      <div class="application-detail__content"></div>
    </section>
    <div class="application-confirm" role="dialog" aria-modal="true" aria-labelledby="application-confirm-title" hidden>
      <h3 id="application-confirm-title">确认操作</h3><p data-confirm-summary></p>
      <div><button type="button" data-action="confirm-application-action">确认</button><button type="button" data-action="cancel-application-action">取消</button></div>
    </div>
  `;

  const status = root.querySelector<HTMLElement>(".application-board__status")!;
  const board = root.querySelector<HTMLElement>('[data-view-panel="board"]')!;
  const list = root.querySelector<HTMLElement>('[data-view-panel="list"]')!;
  const form = root.querySelector<HTMLFormElement>('form[data-form="application"]')!;
  const detail = root.querySelector<HTMLElement>(".application-detail")!;
  const detailContent = root.querySelector<HTMLElement>(".application-detail__content")!;
  const confirmDialog = root.querySelector<HTMLElement>(".application-confirm")!;
  const confirmSummary = root.querySelector<HTMLElement>("[data-confirm-summary]")!;
  const stageSelect = form.elements.namedItem("stageId") as HTMLSelectElement;
  const resumeSelect = form.elements.namedItem("currentResumeId") as HTMLSelectElement;
  let applications: Application[] = [];
  let stages: Stage[] = [];
  let resumes: Resume[] = [];
  let view: "board" | "list" = "board";
  let filter = "";
  let editingId: string | undefined;
  let detailId: string | undefined;
  let pendingAction: { type: "archive" | "delete" | "stage-delete"; id: string; preview: ActionPreview; replacementStageId?: string } | undefined;
  let pendingJobDescriptionId: string | undefined;

  const esc = (value: unknown): string => String(value ?? "").replace(/[&<>'"]/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;" }[char] ?? char));
  const visibleApplications = () => applications.filter((item) => !filter || item.jobType === filter);
  const stageById = (id: string) => stages.find((stage) => stage.id === id);
  const setStatus = (message: string) => { status.textContent = message; };

  function renderApplications(): void {
    const items = visibleApplications();
    board.innerHTML = stages.map((stage) => {
      const cards = items.filter((item) => item.stageId === stage.id).map((item) => `
        <article class="application-card" data-application-id="${esc(item.id)}">
          <h4>${esc(item.company)}</h4><p>${esc(item.position)}</p>
          <p class="application-card__meta">${esc(item.location)} · ${esc(item.jobType)} · ${esc(item.workMode)}</p>
          <p class="application-card__stage" style="--stage-color:${esc(stage.color)}">${esc(stage.name)}</p>
          <p class="application-card__resume">${item.currentResumeId ? `简历：${esc(resumes.find((resume) => resume.id === item.currentResumeId)?.name ?? item.currentResumeId)}` : "未绑定简历"}</p>
          <div class="application-card__actions"><button type="button" data-action="details" data-application-id="${esc(item.id)}">查看详情</button><button type="button" data-action="edit" data-application-id="${esc(item.id)}">编辑</button><button type="button" data-action="advance" data-application-id="${esc(item.id)}">推进阶段</button></div>
        </article>`).join("");
      return `<section class="application-stage-column" data-stage-id="${esc(stage.id)}"><h3><span style="--stage-color:${esc(stage.color)}">${esc(stage.name)}</span><small>${cards ? cards.match(/class="application-card"/g)?.length ?? 0 : 0}</small></h3>${cards || `<p class="application-empty">暂无职位</p>`}</section>`;
    }).join("");
    list.innerHTML = items.map((item) => {
      const stage = stageById(item.stageId);
      return `<article class="application-list-row"><div><strong>${esc(item.company)}</strong><span>${esc(item.position)}</span></div><div>${esc(stage?.name ?? "未知阶段")}</div><div>${esc(item.jobType)}</div><div class="application-row-actions"><button type="button" data-action="details" data-application-id="${esc(item.id)}">详情</button><button type="button" data-action="edit" data-application-id="${esc(item.id)}">编辑</button><button type="button" data-action="advance" data-application-id="${esc(item.id)}">推进</button></div></article>`;
    }).join("") || `<p class="application-empty">暂无职位</p>`;
    board.hidden = view !== "board";
    list.hidden = view !== "list";
    root.querySelectorAll<HTMLButtonElement>("[data-view]").forEach((button) => {
      button.setAttribute("aria-pressed", String(button.dataset.view === view));
    });
    setStatus(`${items.length} 个职位，当前为${view === "board" ? "看板" : "列表"}视图`);
  }

  async function renderStages(): Promise<void> {
    const manager = root.querySelector<HTMLElement>(".stage-manager__list")!;
    manager.innerHTML = stages.map((stage, index) => `<div class="stage-manager__item" data-stage-id="${esc(stage.id)}"><label>阶段名称<input data-stage-name value="${esc(stage.name)}" /></label><label>颜色<input data-stage-color type="color" value="${esc(stage.color)}" /></label><button type="button" data-action="save-stage">保存</button><button type="button" data-action="move-stage-up" ${index === 0 ? "disabled" : ""}>上移</button><button type="button" data-action="move-stage-down" ${index === stages.length - 1 ? "disabled" : ""}>下移</button>${stage.kind === "normal" ? `<button type="button" data-action="delete-stage">删除</button>` : ""}</div>`).join("");
    const counts = await stageService.getOutcomeCounts();
    const countElement = root.querySelector<HTMLElement>(".stage-outcome-counts")!;
    countElement.textContent = `Offer ${counts.offer} · 拒绝 ${counts.rejected} · 放弃 ${counts.withdrawn}`;
    stageSelect.innerHTML = stages.map((stage) => `<option value="${esc(stage.id)}">${esc(stage.name)}</option>`).join("");
  }

  async function load(): Promise<void> {
    try {
      if (stageService.ensureDefaultStages) await stageService.ensureDefaultStages();
      [applications, stages] = await Promise.all([applicationService.listApplications(), stageService.listStages()]);
      resumes = options.resumeLibrary ? await options.resumeLibrary.search("") : [];
      resumeSelect.innerHTML = `<option value="">暂不绑定</option>${resumes.filter((resume) => resume.status !== "deleted").map((resume) => `<option value="${esc(resume.id)}">${esc(resume.name)}</option>`).join("")}`;
      await renderStages();
      renderApplications();
    } catch (error) { setStatus(error instanceof Error ? error.message : "职位读取失败"); }
  }

  function resetForm(): void {
    form.reset();
    editingId = undefined;
    (form.querySelector("[data-form-title]") as HTMLElement).textContent = "创建职位";
    (form.querySelector('[data-action="cancel-edit"]') as HTMLButtonElement).hidden = true;
    if (stages[0]) stageSelect.value = stages[0].id;
  }

  async function showDetail(id: string): Promise<void> {
    const item = applications.find((entry) => entry.id === id);
    if (!item) return;
    detailId = id;
    const [timeline, history, analysisHistory] = await Promise.all([applicationService.listTimeline(id), applicationService.listResumeUsageHistory(id), options.matchingService?.listHistory(id) ?? Promise.resolve([])]);
