tatus" role="status" aria-live="polite"></p><div class="matching-history">${analysisHistory.length ? analysisHistory.map((result) => `<button type="button" class="matching-history__item" data-action="open-analysis" data-analysis-id="${esc(result.id)}">${esc(result.createdAt)} · ${esc(resumes.find((resume) => resume.id === result.resumeId)?.name ?? result.resumeId)}</button>`).join("") : "<p>暂无匹配历史</p>"}</div><div class="matching-current">${analysisHistory[0] ? renderResult(analysisHistory[0]) : ""}</div></section><h4>简历使用历史</h4><ul>${history.map((entry) => `<li>${esc(entry.resumeNameSnapshot)}：${esc(entry.textSnapshot)}</li>`).join("") || "<li>暂无历史</li>"}</ul><h4>时间线</h4><ol>${timeline.map((entry) => `<li>${esc(entry.type)}：${esc(entry.note)}</li>`).join("") || "<li>暂无事件</li>"}</ol>`;
